typedef int (__fastcall *XsCreateUnitFn)(int,int,Vec4*,int,int,int);

static HMODULE g_exe=NULL;
static UnitEntry g_units[MAX_UNITS];
static Category g_cats[MAX_CATS];
static int g_unitCount=0,g_catCount=0;
static int g_view[MAX_UNITS],g_viewCount=0;
static volatile LONG g_selected=0,g_cat=0,g_scroll=0,g_open=0,g_started=0,g_manualVisible=1,g_searchActive=0;
